import type { Item } from './quote.js';

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface Policy {
  items: Item[];
  remainingCap: number;
}

const DEDUCTIBLE = 100;

export function createPolicy(items: Item[]): Policy {
  return { items, remainingCap: 0 };
}

export function claim(policy: Policy, incident: Incident): ClaimResult {
  let payout = 0;
  for (const damage of incident.damages) {
    payout += Math.max(0, damage.amount - DEDUCTIBLE);
  }
  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
}

