const CURSE_SURCHARGE = 0.5;
const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
const HIGH_ENCHANTMENT_THRESHOLD = 5;

/** Item-specific modifiers apply to that item's own base premium. */
function itemPremium(item: Item, base: number): number {
  let premium = base;
  if (item.cursed) premium += base * CURSE_SURCHARGE;
  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
    premium += base * HIGH_ENCHANTMENT_SURCHARGE;
  }
  return premium;
}

export function quote(
  step: QuoteStep,
  customer: Customer,
  previousContracts: number,
): QuoteResult {
  let policyBase = 0;
  let itemSurcharges = 0;
  const componentCounts = new Map<string, number>();

  for (const item of step.items) {
    if (isComponent(item.type)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
      continue;
    }
    const base = BASE_PREMIUMS[item.type];
    if (base === undefined) {
      throw new Error(`unknown item type: ${item.type}`);
    }
    policyBase += base;
    itemSurcharges += itemPremium(item, base) - base;
  }

  for (const count of componentCounts.values()) {
    policyBase += componentsBasePremium(count);
  }

  // Policy-wide modifiers are percentages of the policy base premium —
  // the sum of the unmodified item base premiums.
  let policyModifiers = policyBase * FIRST_INSURANCE_SURCHARGE;
  if (customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS) {
    policyModifiers -= policyBase * LOYALTY_DISCOUNT;
  }
  if (previousContracts > 0) {
    policyModifiers -= policyBase * FOLLOW_UP_DISCOUNT;
  }

  const total = policyBase + itemSurcharges + policyModifiers;

  return { premium: Math.ceil(total + PROCESSING_FEE) };
}

